argv:
$ErrorActionPreference='Stop'
$repo='E:\WebAIBridge'
$target='9a8898a70355bbae2d465ee49739030aa27e9f4e'
$targetBranch='agent/bridge-r44-hotfix-r43-integration-20261007'
$expectedBlob='ca53b0e3a8e1e11ca48e162b72be4ca983e378a3'
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path
function G([string[]]$a){
 $o=& $git -C $repo @a 2>&1;$c=$LASTEXITCODE
 if($c -ne 0){throw "git $($a -join ' ') failed ($c): $o"}
 if($null -eq $o){return ''}
 return ([string]($o -join [Environment]::NewLine)).Trim()
}
$preHead=G @('rev-parse','HEAD')
$preBranch=G @('branch','--show-current')
$null=G @('fetch','origin',$targetBranch)
$resolved=G @('rev-parse',$target)
if($resolved.ToLowerInvariant() -ne $target){throw "target resolve mismatch: $resolved"}
$blob=G @('rev-parse',($target+':app/r42-cutover.ps1'))
if($blob.ToLowerInvariant() -ne $expectedBlob){throw "cutover blob mismatch: $blob"}
$tmp=Join-Path ([IO.Path]::GetTempPath()) ('r44-preflight-owner-20261008-r44-preflight-03-'+[guid]::NewGuid().ToString('N')+'.ps1')
try{
 $psi=New-Object System.Diagnostics.ProcessStartInfo
 $psi.FileName=$git;$psi.WorkingDirectory=$repo;$psi.UseShellExecute=$false
 $psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.CreateNoWindow=$true
 $psi.Arguments='cat-file blob '+$blob
 $p=New-Object System.Diagnostics.Process;$p.StartInfo=$psi
 if(-not $p.Start()){throw 'git cat-file start failed'}
 $fs=[IO.File]::Open($tmp,[IO.FileMode]::Create,[IO.FileAccess]::Write,[IO.FileShare]::None)
 try{$p.StandardOutput.BaseStream.CopyTo($fs)}finally{$fs.Dispose()}
 $err=$p.StandardError.ReadToEnd();$p.WaitForExit()
 if($p.ExitCode -ne 0){throw "cat-file failed: $err"}
 $tmpHash=G @('hash-object','--no-filters','--',$tmp)
 if($tmpHash.ToLowerInvariant() -ne $blob.ToLowerInvariant()){throw "temp bundle hash mismatch: $tmpHash"}
 $out=@(& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $tmp -TargetSha $target -TargetBranch $targetBranch -RepoPath $repo -PreflightOnly 2>&1)
 $exit=$LASTEXITCODE
 $text=[string]($out -join [Environment]::NewLine)
 $last=$null
 for($i=$out.Count-1;$i -ge 0;$i--){$line=[string]$out[$i];if($line.Trim().StartsWith('{')){try{$last=$line|ConvertFrom-Json;break}catch{}}}
 [ordered]@{
  object='owner.r44.local_preflight.v1'
  operationId='owner-20261008-r44-preflight-03'
  sourceTarget=$target
  cutoverBlob=$blob
  preHead=$preHead
  preBranch=$preBranch
  exitCode=$exit
  preflight=$last
  output=$text
  productionSwitchPerformed=$false
  providerMutationPerformed=$false
 }|ConvertTo-Json -Depth 30 -Compress
}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}
